/**
 * Turns the instance definition into the files the stack actually starts from. Everything here is
 * a pure string function except `renderAll` and `renderNginxConf`, the only parts that touch the
 * filesystem.
 */

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { isIPv4 } from 'node:net';
import { dirname, join } from 'node:path';
import { DEV_SERVERS, instanceScopedNginxName, instanceServices, serviceByName } from './services.mjs';
import { stateDirFor } from './compose.mjs';

/** `%%NAME%%`, not `${NAME}` — realm-export carries Keycloak's own `${…}` placeholders. */
export function substitute(template, values) {
  const rendered = template.replace(/%%([A-Z_]+)%%/g, (match, name) => {
    if (name in values) {
      return values[name];
    } else {
      throw new Error(`No value supplied for template placeholder ${match}.`);
    }
  });
  // Broader than the substitution regex above on purpose: a placeholder whose name falls outside
  // `[A-Z_]` (a stray lowercase name, a hyphen) would otherwise match neither regex and be emitted
  // verbatim as a half-rendered template instead of being caught here.
  const leftover = rendered.match(/%%[^%\s]+%%/g);
  if (leftover) {
    throw new Error(`Template still contains ${leftover.join(', ')} after rendering.`);
  } else {
    return rendered;
  }
}

function urls(instance, proxyPort) {
  const url = (name) => serviceByName(instance, name, proxyPort).url;
  return {
    app: url('app'),
    cms: url('cms'),
    boards: url('boards'),
    api: url('api'),
    keycloak: url('keycloak'),
    meilisearch: url('meilisearch'),
    localstack: url('localstack'),
    imgproxy: url('imgproxy'),
    sendinblue: url('sendinblue'),
    sampleImages: url('sample-images'),
    limesurvey: url('limesurvey'),
    tiles: url('tiles'),
  };
}

export function composeEnv(instance, proxyPort) {
  const publicUrl = urls(instance, proxyPort);
  // Host and port both derived from services.mjs rather than re-stated, so renaming a compose
  // service there — or changing its port — cannot silently leave these URLs pointed at a
  // host/port that no longer exists. The :8081 actuator health port below has no home in
  // services.mjs (CONTAINER_SERVICES only tracks the app port, 8080) and stays a literal for
  // that reason, not by oversight.
  const backend = serviceByName(instance, 'api', proxyPort).upstream;
  const keycloak = serviceByName(instance, 'keycloak', proxyPort).upstream;
  const frontendOrigins = [publicUrl.app, publicUrl.cms, publicUrl.boards].join(',');
  return {
    URBO_INSTANCE: instance,
    COMPOSE_PROJECT_NAME: `urbo-${instance}`,

    // The one persisted record of what port this instance was last rendered for. `just urls`,
    // `just open` and `just serve` run in whatever shell a developer happens to have open —
    // `URBO_PROXY_PORT` may not be (re)exported there — so they read it back from here instead of
    // re-deriving or defaulting it themselves. See `compose.mjs`'s `readProxyPort`.
    URBO_PROXY_PORT: String(proxyPort),

    // The browser and the backend must see one identical Keycloak origin, or the JWT issuer check
    // fails. That is the whole reason the shared proxy answers to the public names inside the
    // instance network too.
    KC_HOSTNAME: publicUrl.keycloak,
    SPRING_SECURITY_OAUTH2_RESOURCESERVER_JWT_ISSUER_URI: `${publicUrl.keycloak}/realms/swcode`,
    SPRING_SECURITY_OAUTH2_RESOURCESERVER_JWT_JWK_SET_URI: `${publicUrl.keycloak}/realms/swcode/protocol/openid-connect/certs`,
    KEYCLOAK_MANAGEMENT_URL: publicUrl.keycloak,

    APP_CORS_URLS: frontendOrigins,

=== compose.mjs renderEnv ===
 * same Postgres server, see `docker-compose.yml`'s `POSTGRES_DB2`). Holds the sha256 of the realm
 * `up.mjs` last rendered *and confirmed Keycloak actually imported* — see `realm-drift.mjs` for why
 * a changed realm otherwise goes silently unimported, and `up.mjs`'s `databaseIsFresh` for
 * exactly when that confirmation happens. `cli.mjs`'s `reset` must remove this one too, or a wiped
 * `keycloak` database would be checked against a hash from before the wipe.
 */
export function realmHashMarkerFor(instance) {
  return join(stateDirFor(instance), 'realm-hash');
}

/** The `compose --env-file … -f … <args>` prefix every caller needs, assembled in one place. */
export function composeArgs(instance, args) {
  return ['compose', '--env-file', envFileFor(instance), '-f', COMPOSE_FILE, ...args];
}

/**
 * Reads back the proxy port `just up` last rendered this instance's artifacts for, straight out of
 * its rendered env file (`render.mjs`'s `composeEnv` writes `URBO_PROXY_PORT` there). `just urls`,
 * `just open` and `just serve` run in whatever shell a developer happens to have open —
 * `URBO_PROXY_PORT` may well not be exported there — so they must recover the port from what was
 * actually rendered instead of re-deriving or defaulting it themselves.
 */
export function readProxyPort(instance) {
  const path = envFileFor(instance);
  if (!existsSync(path)) {
    throw new Error(`No rendered environment for "${instance}" at ${path}. Run \`just up\` first.`);
  }
  const match = readFileSync(path, 'utf8').match(/^URBO_PROXY_PORT=(\d+)$/m);
  if (!match) {
    throw new Error(`"${path}" has no URBO_PROXY_PORT recorded — re-render with \`just up\`.`);
  }
  return Number(match[1]);
}

/**
 * Runs a command with inherited stdio (build/seed/log/shell/pnpm/gradle output streams straight to
 * the terminal), resolving with the exit code rather than throwing — every caller decides for
 * itself what a non-zero exit means. The one spawn-and-resolve implementation for every recipe
 * that shells out and waits: `compose`/`composeInteractive` below (against `docker compose`),
 * `up.mjs`'s `pnpm install`, `native.mjs`'s build/sync/open steps, and `backend-local.mjs`'s
 * `gradlew bootRun`.
 */
export function runInherited(command, args, { cwd, env, spawnProcess = spawnResolved } = {}) {
  return new Promise((resolve) => {
    const child = spawnProcess(command, args, { stdio: 'inherit', cwd, env });
    child.on('error', () => resolve(1));
    child.on('close', (code) => resolve(code ?? 1));
  });
}

/**
 * `runInherited`'s quiet sibling, for the long one-shot steps of `just up`. The child's output goes
 * to `logFile` instead of the terminal, and the last `tailLines` lines are kept in hand so a
 * failure can be explained without anyone opening the file. Resolves `{ code, tail }` — never
 * throws, the same contract `runInherited` has, so every caller keeps deciding for itself what a
 * non-zero exit means.
 *
 * Piping rather than inheriting has a second effect worth keeping: the child sees a non-TTY, so
 * `docker compose` drops both its cursor-addressed progress rendering and the navigation menu that
 * `composeEnv` below disables by hand.
 */
